const crypto = require('crypto');

const WATCHDOG_SECRET = '02194db639f32b2e643946d783fae76f74c1b49049efcbcb233c415b812e3f130c4db368b186f5fc2ce354e9e0f07ba7';
const REQUIRE_SIGNATURE = true;
const MAX_CLOCK_SKEW_SECONDS = 15 * 60;
const EXPECTED_SOURCE = 'db-watchdog-agent';

function getHeader(headers, name) {
  const target = String(name).toLowerCase();
  for (const pair of Object.entries(headers || {})) {
    const key = pair[0];
    const value = pair[1];
    if (String(key).toLowerCase() === target) {
      return Array.isArray(value) ? String(value[0] || '') : String(value || '');
    }
  }
  return '';
}

function getRawBody(input) {
  if (typeof input.rawBody === 'string') return input.rawBody;
  if (typeof input.raw_body === 'string') return input.raw_body;
  if (typeof input.bodyRaw === 'string') return input.bodyRaw;
  if (typeof input.body === 'string') return input.body;
  if (input.body && typeof input.body.rawBody === 'string') return input.body.rawBody;
  return JSON.stringify(input.body || {});
}

function parsePayload(input, rawBody) {
  if (input.body && typeof input.body === 'object' && !Array.isArray(input.body)) return input.body;
  if (typeof input.body === 'string' && input.body.trim() !== '') return JSON.parse(input.body);
  if (typeof rawBody === 'string' && rawBody.trim() !== '') return JSON.parse(rawBody);
  return input;
}

function safeTimingEqual(left, right) {
  const leftBuffer = Buffer.from(String(left));
  const rightBuffer = Buffer.from(String(right));
  return leftBuffer.length === rightBuffer.length && crypto.timingSafeEqual(leftBuffer, rightBuffer);
}

const input = items[0] && items[0].json ? items[0].json : {};
const headers = input.headers || {};
const signature = getHeader(headers, 'x-bb-watchdog-signature');
const timestampHeader = getHeader(headers, 'x-bb-watchdog-timestamp');
const rawBody = getRawBody(input);
const payload = parsePayload(input, rawBody);

if (REQUIRE_SIGNATURE) {
  if (!WATCHDOG_SECRET || WATCHDOG_SECRET.indexOf('CHANGE_ME') === 0) {
    throw new Error('Watchdog secret is not configured in n8n.');
  }
  if (!signature) throw new Error('Missing X-BB-Watchdog-Signature header.');

  const expected = 'sha256=' + crypto.createHmac('sha256', WATCHDOG_SECRET).update(rawBody).digest('hex');
  if (!safeTimingEqual(signature, expected)) throw new Error('Invalid watchdog signature.');
}

if (EXPECTED_SOURCE && payload.source !== EXPECTED_SOURCE) {
  throw new Error('Unexpected watchdog source: ' + String(payload.source || ''));
}

const nowSeconds = Math.floor(Date.now() / 1000);
const payloadSeconds = Number(payload.timestamp_epoch || timestampHeader || 0);
if (payloadSeconds > 0 && Math.abs(nowSeconds - payloadSeconds) > MAX_CLOCK_SKEW_SECONDS) {
  throw new Error('Watchdog payload timestamp outside accepted clock skew.');
}

if (!Array.isArray(payload.records)) {
  throw new Error('Watchdog payload does not contain records array.');
}

return [{
  json: Object.assign({}, payload, {
    received_at: new Date().toISOString(),
    n8n_watchdog: {
      signature_required: REQUIRE_SIGNATURE,
      signature_valid: REQUIRE_SIGNATURE ? true : null,
      workflow: EXPECTED_SOURCE
    }
  })
}];

const KNOWN_ADMIN_IDS = new Set(['1', '34', '72', '30328', '32065', '62317', '121806', '136996']);
const RESET_BASELINE = false;
const ALERT_ON_FIRST_RUN_FINDINGS = true;

const state = $getWorkflowStaticData('global');
const payload = items[0] && items[0].json ? items[0].json : {};
const rows = Array.isArray(payload.records) ? payload.records : [];

function stableKey(row) {
  return [row.record_type || 'unknown', row.key_name || '', row.label || ''].join('|');
}

function severityFor(row, reason) {
  if (row.record_type === 'admin_user') return 'critical';
  if (row.record_type === 'watched_option' && row.key_name === 'active_plugins') return 'critical';
  if (row.record_type === 'suspicious_option') return 'critical';
  if (row.record_type === 'wpwebhooks_table') return 'warning';
  if (reason === 'changed') return 'warning';
  return 'warning';
}

function rowSummary(row) {
  return {
    record_type: row.record_type || 'unknown',
    key_name: row.key_name || '',
    label: row.label || '',
    value_hash: row.value_hash || '',
    details: row.details || ''
  };
}

const current = {};
for (const row of rows) {
  const key = stableKey(row);
  current[key] = rowSummary(row);
}

const firstRunFindings = [];
for (const row of rows) {
  if (row.record_type === 'admin_user' && !KNOWN_ADMIN_IDS.has(String(row.key_name))) {
    firstRunFindings.push({
      severity: 'critical',
      reason: 'admin_not_in_allowlist',
      record: rowSummary(row)
    });
  }
  if (row.record_type === 'suspicious_option') {
    firstRunFindings.push({
      severity: 'critical',
      reason: 'suspicious_option_payload',
      record: rowSummary(row)
    });
  }
}

if (RESET_BASELINE || !state.dbBaseline) {
  state.dbBaseline = {
    initialized_at: new Date().toISOString(),
    records: current
  };

  if (ALERT_ON_FIRST_RUN_FINDINGS && firstRunFindings.length) {
    return [{
      json: {
        source: 'db-watchdog',
        severity: firstRunFindings.some(function(f) { return f.severity === 'critical'; }) ? 'critical' : 'warning',
        reason: 'first_run_findings',
        host_id: payload.host_id || '',
        agent_timestamp_utc: payload.timestamp_utc || '',
        findings: firstRunFindings,
        record_count: rows.length,
        baseline_initialized: true,
        checked_at: new Date().toISOString(),
        payload: payload
      }
    }];
  }

  return [];
}

const previous = state.dbBaseline.records || {};
const findings = [];

for (const key of Object.keys(current)) {
  const row = current[key];
  const old = previous[key];
  if (!old) {
    findings.push({
      severity: severityFor(row, 'new'),
      reason: 'new_record',
      record: row
    });
    continue;
  }
  if (String(old.value_hash || '') !== String(row.value_hash || '')) {
    findings.push({
      severity: severityFor(row, 'changed'),
      reason: 'changed',
      old_record: old,
      record: row
    });
  }
}

for (const key of Object.keys(previous)) {
  if (!current[key]) {
    findings.push({
      severity: 'notice',
      reason: 'removed_record',
      old_record: previous[key]
    });
  }
}

state.dbBaseline = {
  initialized_at: state.dbBaseline.initialized_at,
  updated_at: new Date().toISOString(),
  records: current
};

const actionable = findings.filter(function(f) { return f.severity === 'critical' || f.severity === 'warning'; });
if (!actionable.length) return [];

return [{
  json: {
    source: 'db-watchdog',
    severity: actionable.some(function(f) { return f.severity === 'critical'; }) ? 'critical' : 'warning',
    reason: 'db_state_changed',
    host_id: payload.host_id || '',
    agent_timestamp_utc: payload.timestamp_utc || '',
    findings: actionable,
    record_count: rows.length,
    checked_at: new Date().toISOString(),
    payload: payload
  }
}];

const input = items[0] && items[0].json ? items[0].json : {};

function escapeHtml(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function asJson(value) {
  return escapeHtml(JSON.stringify(value || {}, null, 2));
}

const severity = String(input.severity || 'warning').toLowerCase();
const color = severity === 'critical' ? '#b42318' : '#b54708';
const subject = '[BB Watchdog DB] - ' + severity.toUpperCase() + ' - ' + (input.reason || 'db_state_changed');
const findings = Array.isArray(input.findings) ? input.findings : [];
const itemsHtml = findings.map(function(finding) {
  const record = finding.record || finding.old_record || {};
  return '<li><strong>' + escapeHtml(finding.severity || '') + '</strong> '
    + escapeHtml(finding.reason || '')
    + ' - <code>' + escapeHtml(record.record_type || '') + ':' + escapeHtml(record.key_name || '') + '</code>'
    + '<br><small>' + escapeHtml(record.details || '') + '</small></li>';
}).join('');

const html = [
  '<div style="font-family:Arial,Helvetica,sans-serif;color:#1d2939;line-height:1.45;">',
  '<h2 style="margin:0 0 8px;color:' + color + ';">BB DB Watchdog Alert</h2>',
  '<p><strong>Severity:</strong> <span style="color:' + color + ';font-weight:bold;">' + escapeHtml(severity.toUpperCase()) + '</span></p>',
  '<p><strong>Host:</strong> ' + escapeHtml(input.host_id || '') + ' &nbsp; <strong>Agent time:</strong> ' + escapeHtml(input.agent_timestamp_utc || '') + '</p>',
  '<p><strong>Checked at:</strong> ' + escapeHtml(input.checked_at || '') + '</p>',
  '<h3>Findings</h3>',
  '<ul>' + itemsHtml + '</ul>',
  '<h3>Raw Data</h3>',
  '<pre style="white-space:pre-wrap;background:#f6f8fa;padding:12px;border:1px solid #d0d7de;border-radius:6px;overflow:auto;">' + asJson(input) + '</pre>',
  '<p style="color:#667085;font-size:12px;margin-top:24px;">Hinweis: Dieser Workflow empfaengt einen signierten Server-Push. n8n hat keinen MySQL-Zugriff auf den Shop.</p>',
  '</div>'
].join('');

return [{ json: { subject: subject, html: html, event: input } }];
